package dev.zomboid.gore;
import java.util.*;import java.nio.file.*;
public class AnatomyChecks14{
 static int checks;static void ok(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
 static boolean touch(Mesh12.Box a,Mesh12.Box b){float e=.00001f;return a.x0()<=b.x1()+e&&a.x1()+e>=b.x0()&&a.y0()<=b.y1()+e&&a.y1()+e>=b.y0()&&a.z0()<=b.z1()+e&&a.z1()+e>=b.z0();}
 static boolean connected(List<Anatomy14.Piece>p){Set<Integer>seen=new HashSet<>();seen.add(0);boolean more=true;while(more){more=false;for(int i=0;i<p.size();i++)if(!seen.contains(i))for(int j:new ArrayList<>(seen))if(touch(p.get(i).box(),p.get(j).box())){seen.add(i);more=true;break;}}if(seen.size()!=p.size())for(int i=0;i<p.size();i++)if(!seen.contains(i))System.err.println("disconnected="+p.get(i));return seen.size()==p.size();}
 public static void main(String[]args)throws Exception{StringBuilder json=new StringBuilder("[");boolean comma=false;for(int region:new int[]{0,2,3,4,5,6})for(int stage=1;stage<=7;stage++){int packed=region==6?stage|(stage<<5):stage;var pieces=Anatomy14.damaged(region,packed);ok(connected(pieces),"all internal bones, tissue and organs connected at region="+region+" stage="+stage);boolean bounds=true;for(var p:pieces){var b=p.box();bounds&=b.valid()&&b.x0()>=0&&b.y0()>=0&&b.z0()>=0&&b.x1()<=1&&b.y1()<=1&&b.z1()<=1;}ok(bounds,"internal geometry stays inside its part");var cube=new Mesh12.Cube(Mesh12.canonical(region),List.of());var mesh=Anatomy14.build(List.of(cube),region,packed);ok(mesh.size()<1400,"bounded generated mesh");boolean finite=true;for(var quad:mesh)for(var v:quad.vertices())finite&=Float.isFinite(v.x())&&Float.isFinite(v.y())&&Float.isFinite(v.z());ok(finite,"finite render vertices");if(stage==4){for(var p:pieces){if(comma)json.append(',');comma=true;var b=p.box();json.append(String.format(Locale.ROOT,"{\"region\":%d,\"name\":\"%s\",\"material\":%d,\"box\":[%f,%f,%f,%f,%f,%f]}",region,p.name(),p.material(),b.x0(),b.y0(),b.z0(),b.x1(),b.y1(),b.z1()));}}}
 ok(Anatomy14.anatomy(0).stream().anyMatch(p->p.name().equals("jaw_chin")),"jaw exists");for(String name:new String[]{"heart","left_lung","right_lung","liver","stomach","bowel_loop"})ok(Anatomy14.anatomy(6).stream().anyMatch(p->p.name().equals(name)),"organ exists: "+name);
 ok(Artery14.arterial(0,.78,1)&&!Artery14.arterial(0,.95,1),"neck artery trigger differs from high cranium hit");ok(!Artery14.arterial(2,.6,1)&&Artery14.arterial(2,.6,2),"deep limb injury required for arterial pulse");
 List<Anatomy14.Piece> assembled=new ArrayList<>();for(int part:new int[]{0,2,3,4,5,6}){var bounds=Mesh12.canonical(part);float dx=part==2?5:part==3?-5:part==4?1.9f:part==5?-1.9f:0,dy=part==2||part==3?2:part==4||part==5?12:0;for(var piece:Anatomy14.anatomy(part)){var b=Anatomy14.scale(piece.box(),bounds);assembled.add(new Anatomy14.Piece(piece.name(),new Mesh12.Box(b.x0()+dx,b.y0()+dy,b.z0(),b.x1()+dx,b.y1()+dy,b.z1()),piece.material()));}}ok(connected(assembled),"standard humanoid bind pose joins head, shoulders, torso and hips without gaps");
 Files.writeString(Path.of(args[0]),json.append(']').toString());System.out.println("CONNECTED_ANATOMY_PROGRESSIVE_DAMAGE_BOUNDING_AND_ARTERY_CHECKS="+checks);}
}
